/* Author-only GitHub media publishing. This module is never included in reader exports. */
const GH_MEDIA={repo:'chilitiancheng/novel-studio',branch:'main',prefix:'dist/media/',pages:'https://chilitiancheng.github.io/novel-studio/media/'};
let mediaStudioMode='all';
let ghMediaToken='',ghMediaBusy=false,ghMediaAbort=null,ghMediaAuthEpoch=0;
function mediaStatus(message){document.getElementById('mediaStatus').textContent=message;}
function openMediaStudio(view='upload'){const panel=document.getElementById('mediaStudio');if(panel.hidden)panel.scrollTop=0;panel.hidden=false;document.body.classList.add('media-studio-open');setMediaLibraryView(view);}

function setMediaStudioMode(mode){mode=mode==='audio'?'audio':'all';const changed=mediaStudioMode!==mode;mediaStudioMode=mode;const music=mode==='audio',input=document.getElementById('mediaFile');input.accept=music?'.mp3,.m4a,.wav,.ogg':'.jpg,.jpeg,.png,.gif,.webp,.mp4,.mp3,.m4a,.wav,.ogg';input.setAttribute('aria-label',music?'音乐直链文件':'GitHub 素材文件');if(changed)input.value='';document.getElementById('mediaStudioTitle').textContent='GitHub 素材库';document.getElementById('musicLinksHelp').hidden=!music;document.getElementById('mediaUpload').textContent=music?'生成音乐直链并自动填写':'上传并自动填写';document.getElementById('mediaModeAll').setAttribute('aria-pressed',String(!music));document.getElementById('mediaModeMusic').setAttribute('aria-pressed',String(music));}
function requireGitHubMedia(){if(ghMediaToken)return true;openMediaStudio();mediaStatus('请先连接 GitHub。令牌只填在本页面，不要发到聊天里。');return false;}
async function ghMediaFetch(path,options={}){if(!ghMediaToken)throw Error('请先连接 GitHub');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),120000);if(ghMediaAbort)ghMediaAbort.signal.addEventListener('abort',()=>controller.abort(),{once:true});try{const response=await fetch('https://api.github.com/repos/'+GH_MEDIA.repo+path,{...options,headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+ghMediaToken,'X-GitHub-Api-Version':'2022-11-28',...(options.headers||{})},signal:controller.signal,credentials:'omit',redirect:'error'});if(!response.ok)throw Error(response.status===401?'GitHub 令牌无效或已过期':response.status===403?'没有上传权限，请检查当前仓库的 Contents 读写权限':response.status===409?'仓库正在更新，请稍后重试':'GitHub 请求失败（HTTP '+response.status+'）');return await response.json();}finally{clearTimeout(timeout);}}
function bytesBase64(bytes){let result='';for(let i=0;i<bytes.length;i+=32768)result+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(result);}
async function inspectGitHubMedia(file){if(!file||!file.size)throw Error('请选择素材文件');if(file.size>20*1024*1024)throw Error('单个视频最多 20 MiB；图片和音乐最多 4 MiB');const bytes=new Uint8Array(await file.arrayBuffer()),text=(a,b)=>String.fromCharCode(...bytes.slice(a,b));let ext='',kind='',type='';if(bytes[0]===137&&text(1,4)==='PNG'){ext='png';kind='image';type='image/png';}else if(bytes[0]===255&&bytes[1]===216&&bytes[2]===255){ext='jpg';kind='image';type='image/jpeg';}else if(/^GIF8[79]a$/.test(text(0,6))){ext='gif';kind='image';type='image/gif';}else if(text(0,4)==='RIFF'&&text(8,12)==='WEBP'){ext='webp';kind='image';type='image/webp';}else if(text(4,8)==='ftyp'){if(file.type==='audio/mp4'||/\.m4a$/i.test(file.name)){ext='m4a';kind='audio';type='audio/mp4';}else{ext='mp4';kind='video';type='video/mp4';}}else if(text(0,3)==='ID3'||bytes[0]===255&&(bytes[1]&224)===224){ext='mp3';kind='audio';type='audio/mpeg';}else if(text(0,4)==='RIFF'&&text(8,12)==='WAVE'){ext='wav';kind='audio';type='audio/wav';}else if(text(0,4)==='OggS'){ext='ogg';kind='audio';type='audio/ogg';}if(!ext)throw Error('支持 JPG、PNG、GIF、WebP、MP4 视频及 MP3/M4A/WAV/OGG 音乐');if(kind!=='video'&&file.size>4*1024*1024)throw Error('图片和音乐最多 4 MiB，请压缩后再上传');if(kind==='image')await readImageFile(file);return {bytes,ext,kind,type};}
function video(text=''){return editBlock('video','视频',`<div class="picture-fields">${editField('','video-url','视频 MP4 直链 HTTPS')}<button data-action="upload-video" type="button">上传 MP4 到 GitHub 并填写</button><p class="flash-editor-note">示例和小工具可设置进入本页自动播放；AO3 保留手动播放。短视频以 JS 数据打包，控制在 6 MiB 以内。</p></div>${editBody(paragraphs(text))}`);}
function renderVideo(source){const url=imageLink(fieldText(source,'video-url'));if(imageTarget==='ao3'&&!url)throw Error('请上传 MP4 或填写视频 HTTPS 直链');return '<div class="video-scene">'+(url?'<video class="story-video'+(fieldText(source,'media-autoplay')==='yes'&&imageTarget!=='ao3'?' media-auto-enabled':'')+'" controls preload="none" playsinline src="'+esc(url)+'"></video>':'<div class="picture-empty">请上传 MP4 或填写视频直链</div>')+'<div class="picture-caption">'+partsHTML(renderParts(source.querySelector('[data-field=body]')))+'</div></div>';}
function appendVideoFields(fields,source){appendAutoPlaySetting(fields,source);const label=document.createElement('label'),input=document.createElement('input');label.textContent='视频 MP4 直链 HTTPS';input.dataset.graphField='video-url';input.value=fieldText(source,'video-url');label.append(input);fields.append(label);appendGitHubUpload(fields,source,'video');const note=document.createElement('p');note.className='flash-editor-note';note.textContent='MP4 在 AO3 手动播放；示例和小红书可设置自动播放。短视频建议 H.264 编码，以 JS 数据打包，控制在 6 MiB 以内，发布前请在模拟器与真机验证。';fields.append(note);}
function makeMediaAnchor(source,field){graphProjection(editor);return {work:book.id,chapter:book.active,node:source.dataset.nodeId,field,expected:fieldText(source,field)};}
function fillMediaAnchor(anchor,url){let owner=anchor.work===book.id?book:workLibrary.get(anchor.work)?.book;if(!owner)return false;const chapter=owner.chapters.find(c=>c.id===anchor.chapter);if(!chapter)return false;let root,live=anchor.work===book.id&&anchor.chapter===book.active;if(live)root=editor;else{root=document.createElement('div');root.innerHTML=chapter.html;}const source=[...root.querySelectorAll('[data-node-id]')].find(el=>el.dataset.nodeId===anchor.node),field=source?.querySelector('[data-field="'+anchor.field+'"]');if(!field||anchor.expected!==undefined&&field.textContent.trim()!==anchor.expected)return false;if(live)checkpoint();field.textContent=url;if(live){checkpoint();if(graphView)renderGraph(source);}else{chapter.html=root.innerHTML;if(anchor.work!==book.id){const record=workLibrary.get(anchor.work);if(record.book.active===chapter.id)record.html=chapter.html;record.savedAt=new Date().toISOString();}persist();}return true;}
function chooseAutoMediaTarget(info){let item=graphNodes.get(graphSelection),source=item?.kind==='effect'?item.source:null,field='';if(info.kind==='image'){if(source?.dataset.widget==='flash'||source?.dataset.pageFlash==='yes')field=info.ext==='gif'?'flash-gif-url':'image-url';else if(['image','polaroid'].includes(source?.dataset.widget))field='image-url';else if(source?.dataset.widget==='player')field='cover-url';else if(source?.dataset.widget==='sms')field='sms-avatar';}else if(info.kind==='video'&&source?.dataset.widget==='video')field='video-url';else if(info.kind==='audio'&&source?.dataset.widget==='player')field='audio-url';if(field)return {source,field};const factory=info.kind==='image'?picture:info.kind==='video'?video:player;graphMutate(()=>{const div=document.createElement('div');div.innerHTML=factory('');source=div.firstElementChild;if(item?.kind==='choice')item.owner.prepend(source);else if(item?.source?.isConnected)item.source.after(source);else editor.append(source);graphExpanded.add(source);return source;});return {source,field:info.kind==='image'?'image-url':info.kind==='video'?'video-url':'audio-url'};}
async function mediaURLReady(url,type,signal){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);if(signal)signal.addEventListener('abort',()=>controller.abort(),{once:true});try{const response=await fetch(url+'?ready='+Date.now(),{method:'HEAD',cache:'no-store',credentials:'omit',signal:controller.signal});const mime=(response.headers.get('content-type')||'').toLowerCase();return response.ok&&(type.startsWith('image/')?mime.startsWith('image/'):type.startsWith('video/')?mime.startsWith('video/'):mime.startsWith('audio/'));}catch(error){return false;}finally{clearTimeout(timeout);}}
async function waitForMediaURL(url,type,signal){const end=Date.now()+240000;while(Date.now()<end){if(signal.aborted)throw Error('上传已取消；已提交的素材仍保留在 GitHub');if(await mediaURLReady(url,type,signal))return true;await new Promise(resolve=>setTimeout(resolve,3000));}return false;}
function mediaResult(url,anchor,type,ready){const row=document.createElement('div');row.className='media-result';const input=document.createElement('input');input.readOnly=true;input.value=url;input.setAttribute('aria-label',type.startsWith('audio/')?'GitHub 音乐直链':'GitHub 素材直链');const state=document.createElement('span');state.textContent=ready?'直链已就绪':'已上传，等待 Pages 部署';const copy=document.createElement('button');copy.textContent='复制直链';copy.onclick=async()=>{try{await navigator.clipboard.writeText(url);state.textContent='已复制';}catch{input.select();state.textContent='请复制选中的链接';}};const apply=document.createElement('button');apply.textContent='检查并填写';apply.onclick=async()=>{apply.disabled=true;try{if(!await mediaURLReady(url,type))return state.textContent='部署尚未就绪，请稍后重试';state.textContent=fillMediaAnchor(anchor,url)?'已填写到原作品节点':'原节点已变更，请复制直链手动填写';}finally{apply.disabled=false;}};row.append(input,state,copy,apply);document.getElementById('mediaResults').prepend(row);return state;}
async function uploadGitHubMedia(file,target=null){if(!workLibraryReady)return mediaStatus('工作台正在恢复草稿，请稍候再上传');if(!requireGitHubMedia())return;openMediaStudio();if(ghMediaBusy)return mediaStatus('已有素材正在上传或等待部署，请稍候');ghMediaBusy=true;ghMediaAbort=new AbortController();const signal=ghMediaAbort.signal;document.getElementById('mediaUpload').disabled=true;let committed=false;try{mediaStatus('正在读取素材…');const info=await inspectGitHubMedia(file);if(!target&&mediaStudioMode==='audio'&&info.kind!=='audio')throw Error('音乐直链工具请选择 MP3、M4A、WAV 或 OGG 音乐文件');if(signal.aborted||!ghMediaToken)throw Error('上传已取消');if(target){const expected=target.field==='video-url'?'video':target.field==='audio-url'?'audio':'image';if(info.kind!==expected||target.field==='flash-gif-url'&&info.ext!=='gif')throw Error('素材类型与目标节点不匹配，请选择对应的图片、GIF、MP4 或音乐');}if(!target)target=chooseAutoMediaTarget(info);if(!target.source?.isConnected)throw Error('目标节点已移除，请重新选择');if(info.kind==='image'&&target.field==='image-url'&&target.source.querySelector('[data-field=image-asset]'))await attachPictureFile(target.source,file);const anchor=makeMediaAnchor(target.source,target.field),name='media-'+Date.now().toString(36)+'-'+(crypto.randomUUID?crypto.randomUUID().replace(/-/g,''):Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2))+'.'+info.ext,path=GH_MEDIA.prefix+name;mediaStatus('正在上传到 GitHub…');await ghMediaFetch('/contents/'+path,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:'Upload story media '+name,branch:GH_MEDIA.branch,content:bytesBase64(info.bytes)})});committed=true;const url=GH_MEDIA.pages+name,state=mediaResult(url,anchor,info.type,false);if(mediaLibraryLoaded)refreshMediaLibrary(true);mediaStatus('已上传，正在等待 GitHub Pages 部署（可能需要几分钟）。就绪后自动填写，请先不要刷新本页。');const ready=await waitForMediaURL(url,info.type,signal);if(ready){const filled=fillMediaAnchor(anchor,url);state.textContent=filled?'直链已就绪，已自动填写到原节点':'直链已就绪；原节点已变更，请复制后手动填写';mediaStatus(filled?'上传成功，直链已自动填写。':'上传成功，可复制素材直链。');}else mediaStatus('GitHub 已保存素材，Pages 部署尚未就绪。稍后可点「检查并填写」。');}catch(error){mediaStatus((committed?'素材已提交至 GitHub；':'')+(error.name==='AbortError'?'网络超时或已取消，请检查 GitHub 后再重试':error.message||'上传失败'));}finally{ghMediaBusy=false;ghMediaAbort=null;document.getElementById('mediaUpload').disabled=false;document.querySelectorAll('.media-remove').forEach(button=>button.disabled=false);}}
function pickGitHubMedia(source,field,accept){if(!requireGitHubMedia())return;const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>{if(input.files[0])uploadGitHubMedia(input.files[0],{source,field});};input.click();}
function appendGitHubUpload(fields,source,kind){const button=document.createElement('button');button.type='button';button.textContent=kind==='flash'?'生成 GIF → GitHub → 自动填写':kind==='image'?'上传图片 → GitHub → 自动填写':kind==='video'?'上传 MP4 → GitHub → 自动填写':'生成音乐直链并自动填写';button.onclick=async()=>{setMediaStudioMode(['flash','image','video'].includes(kind)?'all':'audio');if(!requireGitHubMedia())return;if(kind==='flash'){try{const blob=await makeFlashGIF(source);await uploadGitHubMedia(new File([blob],'flash.gif',{type:'image/gif'}),{source,field:'flash-gif-url'});}catch(error){mediaStatus(error.message);}}else if(kind==='image'){const asset=imageAssets[fieldText(source,'image-asset')];if(asset){const bytes=Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0));uploadGitHubMedia(new File([bytes],asset.name,{type:asset.type}),{source,field:'image-url'});}else pickGitHubMedia(source,'image-url','.png,.jpg,.jpeg,.gif,.webp');}else if(kind==='video')pickGitHubMedia(source,'video-url','.mp4');else{const asset=musicAssets[fieldText(source,'audio-url').replace(/^paper-audio:/,'')];if(asset)uploadGitHubMedia(new File([Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0))],asset.name,{type:asset.type}),{source,field:'audio-url'});else pickGitHubMedia(source,'audio-url','.mp3,.m4a,.wav,.ogg');}};fields.append(button);}
document.getElementById('openMediaStudio').onclick=()=>{setMediaStudioMode('all');openMediaStudio('library');};
document.getElementById('mediaModeAll').onclick=()=>setMediaStudioMode('all');
document.getElementById('mediaModeMusic').onclick=()=>setMediaStudioMode('audio');
function closeMediaStudio(){document.getElementById('mediaStudio').querySelectorAll('video,audio').forEach(el=>el.pause());document.getElementById('mediaStudio').hidden=true;document.body.classList.remove('media-studio-open');}
document.getElementById('closeMediaStudio').onclick=closeMediaStudio;
document.getElementById('mediaConnect').onclick=async()=>{const input=document.getElementById('githubMediaToken'),token=input.value.trim();input.value='';if(!token)return mediaStatus('请在本页输入 GitHub 上传令牌');const epoch=++ghMediaAuthEpoch;ghMediaToken=token;document.getElementById('mediaConnect').disabled=true;try{const repo=await ghMediaFetch('');if(epoch!==ghMediaAuthEpoch)return;if(repo.full_name!==GH_MEDIA.repo||repo.private)throw Error('目标仓库不匹配或不是公开仓库');mediaStatus('已连接 GitHub，可以选择素材上传。令牌不会随草稿或 ZIP 保存。');document.getElementById('mediaConnection').textContent='已连接';if(!document.getElementById('mediaLibraryPanel').hidden)refreshMediaLibrary(true);}catch(error){if(epoch!==ghMediaAuthEpoch)return;ghMediaToken='';document.getElementById('mediaConnection').textContent='未连接';mediaStatus(error.message);}finally{document.getElementById('mediaConnect').disabled=false;}};
document.getElementById('mediaDisconnect').onclick=()=>{ghMediaAuthEpoch++;ghMediaToken='';if(ghMediaAbort)ghMediaAbort.abort();document.getElementById('githubMediaToken').value='';document.getElementById('mediaConnection').textContent='未连接';mediaStatus('已断开授权；GitHub 中已经上传的素材会保留。');};
document.getElementById('mediaUpload').onclick=()=>{const file=document.getElementById('mediaFile').files[0];if(!file)return mediaStatus('请先选择素材，或拖入下方区域');uploadGitHubMedia(file);};
const mediaDrop=document.getElementById('mediaDrop');mediaDrop.addEventListener('dragover',event=>event.preventDefault());mediaDrop.addEventListener('drop',event=>{event.preventDefault();const file=event.dataTransfer.files[0];if(file)uploadGitHubMedia(file);});
document.addEventListener('click',event=>{const button=event.target.closest('[data-action=upload-video]');if(button)pickGitHubMedia(button.closest('[data-widget=video]'),'video-url','.mp4');});
window.addEventListener('pagehide',()=>{ghMediaAuthEpoch++;ghMediaToken='';if(ghMediaAbort)ghMediaAbort.abort();document.getElementById('githubMediaToken').value='';});

window.addEventListener('pageshow',()=>{if(!ghMediaToken)document.getElementById('mediaConnection').textContent='未连接';});

/* Public media browsing; GitHub authorization is used only for repository operations. */
let mediaLibraryItems=[],mediaLibraryLoaded=false,mediaLibraryFetchedAt=0,mediaLibraryGeneration=0,mediaDeleteTarget=null,mediaModalFocus=null,mediaLibrarySearchTimer;
const MEDIA_LIBRARY_DIRS=['dist/media/','dist/audio/'];
function mediaLibraryNotice(message){document.getElementById('mediaLibraryStatus').textContent=message;}
function setMediaLibraryView(view){const library=view==='library';if(!library)document.getElementById('mediaLibraryGrid').querySelectorAll('video,audio').forEach(el=>el.pause());document.getElementById('mediaUploadPanel').hidden=library;document.getElementById('mediaLibraryPanel').hidden=!library;document.getElementById('mediaTabLibrary').setAttribute('aria-pressed',String(library));document.getElementById('mediaTabUpload').setAttribute('aria-pressed',String(!library));document.getElementById('mediaStudioTitle').textContent=library?'GitHub 素材库':mediaStudioMode==='audio'?'GitHub 音乐直链工具':'GitHub 素材上传';if(library){if(!mediaLibraryLoaded||Date.now()-mediaLibraryFetchedAt>300000)refreshMediaLibrary();else renderMediaLibrary();}}
function mediaLibraryItem(file){if(!file||file.type!=='file'||typeof file.path!=='string'||typeof file.sha!=='string'||!MEDIA_LIBRARY_DIRS.some(dir=>file.path.startsWith(dir)))return null;const dir=MEDIA_LIBRARY_DIRS.find(prefix=>file.path.startsWith(prefix)),name=file.path.slice(dir.length);if(!name||/[\\/\x00-\x1f]/.test(name)||name.startsWith('.'))return null;const ext=name.split('.').pop().toLowerCase(),types={png:['image','image/png'],jpg:['image','image/jpeg'],jpeg:['image','image/jpeg'],gif:['image','image/gif'],webp:['image','image/webp'],mp4:['video','video/mp4'],mp3:['audio','audio/mpeg'],m4a:['audio','audio/mp4'],wav:['audio','audio/wav'],ogg:['audio','audio/ogg']};if(!Object.prototype.hasOwnProperty.call(types,ext))return null;const root=GH_MEDIA.pages.slice(0,GH_MEDIA.pages.lastIndexOf('media/'));return {path:file.path,name,sha:file.sha,size:Number(file.size)||0,ext,kind:types[ext][0],type:types[ext][1],url:root+dir.slice(5)+encodeURIComponent(name)};}
function mediaLibraryAPIPath(path){return '/contents/'+path.split('/').map(encodeURIComponent).join('/');}
async function readMediaLibraryAPI(path){const token=ghMediaToken,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);try{const response=await fetch('https://api.github.com/repos/'+GH_MEDIA.repo+path,{headers:{Accept:'application/vnd.github+json',...(token?{Authorization:'Bearer '+token}:{})},cache:'no-store',credentials:'omit',redirect:'error',signal:controller.signal});if(response.status===404)return null;if(!response.ok)throw Error(response.status===401?'GitHub 授权已过期，请重新连接':response.status===403?'GitHub 读取受限，请连接 GitHub 或稍后重试':'读取素材库失败（HTTP '+response.status+'）');return await response.json();}finally{clearTimeout(timeout);}}
async function refreshMediaLibrary(force=false){if(!force&&mediaLibraryLoaded&&Date.now()-mediaLibraryFetchedAt<300000)return renderMediaLibrary();const generation=++mediaLibraryGeneration,button=document.getElementById('mediaLibraryRefresh');button.disabled=true;mediaLibraryNotice('正在读取已上传素材…');try{const results=await Promise.allSettled(MEDIA_LIBRARY_DIRS.map(dir=>readMediaLibraryAPI(mediaLibraryAPIPath(dir.slice(0,-1))+'?ref='+encodeURIComponent(GH_MEDIA.branch))));let all=[],large=false;for(const result of results){if(result.status==='rejected')throw result.reason;if(result.value===null)continue;if(!Array.isArray(result.value))throw Error('素材目录响应异常，请刷新重试');all.push(...result.value);if(result.value.length>=1000)large=true;}if(large){const tree=await readMediaLibraryAPI('/git/trees/'+encodeURIComponent(GH_MEDIA.branch)+'?recursive=1');if(!tree||!Array.isArray(tree.tree)||tree.truncated)throw Error('素材列表暂未完整读取，请稍后刷新');all=tree.tree.filter(item=>item.type==='blob').map(item=>({...item,type:'file'}));}if(generation!==mediaLibraryGeneration)return;const unique=new Map();for(const file of all){const entry=mediaLibraryItem(file);if(entry)unique.set(entry.path,entry);}const stamp=item=>{const match=item.name.match(/^media-([a-z0-9]+)-/i);return match?parseInt(match[1],36)||0:0;};mediaLibraryItems=[...unique.values()].sort((a,b)=>stamp(b)-stamp(a)||a.name.localeCompare(b.name));mediaLibraryLoaded=true;mediaLibraryFetchedAt=Date.now();renderMediaLibrary();}catch(error){if(generation===mediaLibraryGeneration)mediaLibraryNotice(error.name==='AbortError'?'读取超时，请刷新重试':error.message||'读取素材库失败');}finally{if(generation===mediaLibraryGeneration)button.disabled=false;}}
function mediaReferenceKey(value){try{const url=new URL(value.trim());return url.origin+url.pathname;}catch{return '';}}
function collectMediaLibraryReferences(){const refs=new Map();if(typeof workLibraryReady==='undefined'||!workLibraryReady||!book)return refs;const works=[{id:book.id,title:book.title,chapters:book.chapters,current:true}];for(const [id,record] of workLibrary){if(id===book.id)continue;const owner=record.book;if(owner&&Array.isArray(owner.chapters))works.push({id,title:owner.title,chapters:owner.chapters,current:false});}for(const work of works)for(const chapter of work.chapters){const host=document.createElement('div');host.innerHTML=work.current&&chapter.id===book.active?editor.innerHTML:chapter.html;for(const field of host.querySelectorAll('[data-field=image-url],[data-field=cover-url],[data-field=video-url],[data-field=audio-url],[data-field=flash-gif-url],[data-field=sms-avatar],[data-sound-url]')){const raw=field.hasAttribute('data-sound-url')?field.dataset.soundUrl:field.textContent,key=mediaReferenceKey(raw);if(!key)continue;const item={work:work.id,chapter:chapter.id,label:(work.title||'未命名作品')+' / '+(chapter.title||'未命名章节'),node:field.closest('[data-node-id]')?.dataset.nodeId||'',field:field.dataset.field||'页面音效'};if(!refs.has(key))refs.set(key,[]);refs.get(key).push(item);}}return refs;}
function mediaLibraryPreviewElement(entry,large=false){let element;if(entry.kind==='image'){element=document.createElement('img');element.src=entry.url;element.alt=entry.name;element.loading='lazy';element.decoding='async';element.referrerPolicy='no-referrer';if(!large){element.tabIndex=0;element.setAttribute('role','button');element.setAttribute('aria-label','放大预览 '+entry.name);element.onclick=()=>previewMediaLibraryItem(entry);element.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();previewMediaLibraryItem(entry);}};}}else{element=document.createElement(entry.kind==='video'?'video':'audio');element.src=entry.url;element.controls=true;element.preload=entry.kind==='video'?'metadata':'none';element.setAttribute('aria-label','预览 '+entry.name);if(entry.kind==='video'){element.playsInline=true;element.addEventListener('loadedmetadata',()=>{try{if(element.duration>0)element.currentTime=Math.min(.01,element.duration/2);}catch{}});}}element.addEventListener('error',()=>{const parent=element.parentElement;if(!parent||parent.querySelector('.media-library-error'))return;const note=document.createElement('span');note.className='media-library-error';note.textContent=entry.kind==='video'?'暂时无法预览，可稍后刷新或检查视频编码':'预览暂未就绪，请稍后刷新';parent.append(note);});return element;}
function renderMediaLibrary(){const grid=document.getElementById('mediaLibraryGrid'),filter=document.getElementById('mediaLibraryFilter').value,query=document.getElementById('mediaLibrarySearch').value.trim().toLowerCase(),references=collectMediaLibraryReferences(),items=mediaLibraryItems.filter(item=>(filter==='all'||item.kind===filter)&&(!query||item.name.toLowerCase().includes(query)));grid.replaceChildren();mediaLibraryNotice('共 '+mediaLibraryItems.length+' 个素材'+(items.length!==mediaLibraryItems.length?'，当前显示 '+items.length+' 个':'')+'。'+(!ghMediaToken?'浏览和使用无需令牌；删除前请连接 GitHub。':''));if(!items.length){const empty=document.createElement('div');empty.className='media-library-empty';empty.textContent=mediaLibraryItems.length?'没有匹配的素材，试试切换筛选或搜索条件。':'还没有已上传素材，可切换到「上传新素材」。';grid.append(empty);return;}for(const entry of items){const card=document.createElement('article');card.className='media-library-card';card.dataset.mediaPath=entry.path;const preview=document.createElement('div');preview.className='media-library-preview';preview.append(mediaLibraryPreviewElement(entry));if(entry.kind==='video'){const expand=document.createElement('button');expand.type='button';expand.textContent='放大';expand.onclick=()=>previewMediaLibraryItem(entry);preview.append(expand);}const name=document.createElement('p');name.className='media-library-name';name.textContent=entry.name;name.title=entry.name;const detail=document.createElement('div');detail.className='media-library-detail';const refs=references.get(mediaReferenceKey(entry.url))||[];detail.textContent=entry.ext.toUpperCase()+' · '+(entry.size>=1024*1024?(entry.size/1024/1024).toFixed(1)+' MiB':Math.max(1,Math.round(entry.size/1024))+' KiB')+' · '+(refs.length?'引用 '+refs.length+' 处':'未发现工作台引用');if(refs.length){detail.classList.add('media-library-used');detail.title=refs.map(ref=>ref.label).join('\n');}const actions=document.createElement('div');actions.className='media-library-actions';const use=document.createElement('button');use.type='button';use.textContent='使用素材';use.onclick=()=>selectMediaLibraryItem(entry,use);const copy=document.createElement('button');copy.type='button';copy.textContent='复制直链';copy.onclick=async()=>{try{await navigator.clipboard.writeText(entry.url);mediaLibraryNotice('已复制直链。');}catch{const input=document.createElement('input');input.readOnly=true;input.value=entry.url;input.setAttribute('aria-label','可复制的素材直链');actions.append(input);input.select();mediaLibraryNotice('请复制已选中的直链。');}};const remove=document.createElement('button');remove.type='button';remove.className='media-remove';remove.textContent='删除';remove.disabled=ghMediaBusy;remove.onclick=()=>requestMediaLibraryDelete(entry);actions.append(use,copy,remove);card.append(preview,name,detail,actions);grid.append(card);}}
async function selectMediaLibraryItem(entry,button){if(typeof workLibraryReady==='undefined'||!workLibraryReady)return mediaLibraryNotice('草稿正在恢复，请稍后再使用素材。');const work=book.id,chapter=book.active,selection=graphSelection;button.disabled=true;mediaLibraryNotice('正在检查素材直链…');try{if(!await mediaURLReady(entry.url,entry.type))return mediaLibraryNotice('素材直链暂未就绪，请等待网站更新后重试。');if(work!==book.id||chapter!==book.active||selection!==graphSelection)return mediaLibraryNotice('当前编辑位置已切换，请重新选择素材。');const target=chooseAutoMediaTarget(entry);if(!target.source?.isConnected)throw Error('当前节点已移除，请重新选择');checkpoint();if(entry.kind==='image'&&target.field==='image-url'){const local=target.source.querySelector('[data-field=image-asset]');if(local)local.textContent='';}const anchor=makeMediaAnchor(target.source,target.field);if(!fillMediaAnchor(anchor,entry.url))throw Error('节点已变化，请重新选择素材');renderMediaLibrary();mediaLibraryNotice('已使用素材，填入当前'+(entry.kind==='video'?'视频':entry.kind==='audio'?'音乐播放器':'图片相关')+'节点。');}catch(error){mediaLibraryNotice(error.message||'使用素材失败');}finally{button.disabled=false;}}
function previewMediaLibraryItem(entry){document.getElementById('mediaLibraryGrid').querySelectorAll('video,audio').forEach(el=>el.pause());mediaModalFocus=document.activeElement;document.getElementById('mediaPreviewTitle').textContent=entry.name;const content=document.getElementById('mediaPreviewContent');content.replaceChildren(mediaLibraryPreviewElement(entry,true));document.getElementById('mediaPreviewDialog').hidden=false;document.getElementById('mediaPreviewClose').focus();}
function closeMediaLibraryPreview(){const content=document.getElementById('mediaPreviewContent');content.querySelectorAll('video,audio').forEach(el=>el.pause());content.replaceChildren();document.getElementById('mediaPreviewDialog').hidden=true;if(mediaModalFocus?.isConnected)mediaModalFocus.focus();}
function mediaDeleteReferences(entry){return collectMediaLibraryReferences().get(mediaReferenceKey(entry.url))||[];}
function requestMediaLibraryDelete(entry){if(!requireGitHubMedia())return;if(ghMediaBusy)return mediaLibraryNotice('已有素材操作进行中，请稍候。');if(!mediaLibraryItem({...entry,type:'file'}))return mediaLibraryNotice('此文件不在可管理的素材目录内。');mediaModalFocus=document.activeElement;mediaDeleteTarget=entry;document.getElementById('mediaDeleteName').textContent=entry.name;const refs=mediaDeleteReferences(entry),list=document.getElementById('mediaDeleteReferences');list.replaceChildren();if(refs.length){for(const ref of refs){const item=document.createElement('li');item.textContent=ref.label;list.append(item);}}else{const item=document.createElement('li');item.textContent='未发现当前浏览器作品库中的引用。已导出或其它设备上的外链无法检测。';list.append(item);}document.getElementById('mediaDeleteAcknowledgeLabel').hidden=!refs.length;document.getElementById('mediaDeleteAcknowledge').checked=false;document.getElementById('mediaDeleteConfirm').disabled=!!refs.length;document.getElementById('mediaDeleteStatus').textContent=refs.length?'检测到 '+refs.length+' 处引用，请确认影响后再删除。':'';document.getElementById('mediaDeleteDialog').hidden=false;document.getElementById('mediaDeleteCancel').focus();}
function closeMediaLibraryDelete(){if(ghMediaBusy)return;mediaDeleteTarget=null;document.getElementById('mediaDeleteDialog').hidden=true;if(mediaModalFocus?.isConnected)mediaModalFocus.focus();}
async function confirmMediaLibraryDelete(){const entry=mediaDeleteTarget;if(!entry||ghMediaBusy||!ghMediaToken)return;if(!mediaLibraryItem({...entry,type:'file'}))return;const refs=mediaDeleteReferences(entry);if(refs.length&&!document.getElementById('mediaDeleteAcknowledge').checked)return requestMediaLibraryDelete(entry);const epoch=ghMediaAuthEpoch;ghMediaBusy=true;ghMediaAbort=new AbortController();document.getElementById('mediaUpload').disabled=true;document.getElementById('mediaDeleteConfirm').disabled=true;document.getElementById('mediaDeleteCancel').disabled=true;document.getElementById('mediaDeleteStatus').textContent='正在核对并删除素材…';try{const path=mediaLibraryAPIPath(entry.path),latest=await ghMediaFetch(path+'?ref='+encodeURIComponent(GH_MEDIA.branch));if(epoch!==ghMediaAuthEpoch||!ghMediaToken)throw Error('授权已变化，删除已取消');if(latest.type!=='file'||latest.path!==entry.path||latest.sha!==entry.sha)throw Error('素材已在 GitHub 上更新，请刷新素材库后重新确认');if(mediaDeleteReferences(entry).length&&!document.getElementById('mediaDeleteAcknowledge').checked)throw Error('操作期间出现了新的作品引用，请取消并重新确认删除。');await ghMediaFetch(path,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:'Delete story media '+entry.name,sha:latest.sha,branch:GH_MEDIA.branch})});mediaLibraryItems=mediaLibraryItems.filter(item=>item.path!==entry.path);for(const row of document.querySelectorAll('.media-result'))if(row.querySelector('input')?.value===entry.url)row.remove();mediaDeleteTarget=null;document.getElementById('mediaDeleteDialog').hidden=true;renderMediaLibrary();mediaLibraryNotice('素材已删除，直链会在网站更新后失效。');}catch(error){document.getElementById('mediaDeleteStatus').textContent=error.name==='AbortError'?'操作已中断，可能已提交删除，请刷新素材库确认。':error.message||'删除失败，请刷新后重试。';}finally{ghMediaBusy=false;ghMediaAbort=null;document.getElementById('mediaUpload').disabled=false;document.getElementById('mediaDeleteCancel').disabled=false;document.querySelectorAll('.media-remove').forEach(button=>button.disabled=false);if(mediaDeleteTarget)document.getElementById('mediaDeleteConfirm').disabled=mediaDeleteReferences(mediaDeleteTarget).length>0&&!document.getElementById('mediaDeleteAcknowledge').checked;}}
document.getElementById('mediaTabLibrary').onclick=()=>setMediaLibraryView('library');
document.getElementById('mediaTabUpload').onclick=()=>setMediaLibraryView('upload');
document.getElementById('mediaLibraryRefresh').onclick=()=>refreshMediaLibrary(true);
document.getElementById('mediaLibraryFilter').onchange=renderMediaLibrary;
document.getElementById('mediaLibrarySearch').oninput=()=>{clearTimeout(mediaLibrarySearchTimer);mediaLibrarySearchTimer=setTimeout(renderMediaLibrary,150);};
document.getElementById('mediaPreviewClose').onclick=closeMediaLibraryPreview;
document.getElementById('mediaDeleteCancel').onclick=closeMediaLibraryDelete;
document.getElementById('mediaDeleteAcknowledge').onchange=()=>{document.getElementById('mediaDeleteConfirm').disabled=mediaDeleteTarget&&mediaDeleteReferences(mediaDeleteTarget).length>0&&!document.getElementById('mediaDeleteAcknowledge').checked;};
document.getElementById('mediaDeleteConfirm').onclick=confirmMediaLibraryDelete;
document.addEventListener('keydown',event=>{const preview=document.getElementById('mediaPreviewDialog'),deletion=document.getElementById('mediaDeleteDialog'),studio=document.getElementById('mediaStudio'),modal=!deletion.hidden?deletion:!preview.hidden?preview:!studio.hidden?studio:null;if(!modal)return;if(event.key==='Escape'){event.preventDefault();if(modal===preview)closeMediaLibraryPreview();else if(modal===deletion)closeMediaLibraryDelete();else closeMediaStudio();}if(event.key==='Tab'){const controls=[...modal.querySelectorAll('button,input,select,textarea,[tabindex="0"],video[controls],audio[controls]')].filter(el=>!el.disabled&&!el.closest('[hidden]'));if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
